import{z as o,x as p,o as E,c as A,q as n,j as s,D as t,d as r,s as i,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"权衡理论与破产成本","description":"","frontmatter":{"title":"权衡理论与破产成本","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/tradeoff-capital.md","filePath":"econ/tradeoff-capital.md","lastUpdated":1791063341000}'),d={name:"econ/tradeoff-capital.md"};function D(m,a,u,c,f,h){const l=p("Mermaid");return E(),A("div",null,[a[2]||(a[2]=n('<h1 id="权衡理论与破产成本" tabindex="-1">权衡理论与破产成本 <a class="header-anchor" href="#权衡理论与破产成本" aria-label="Permalink to &quot;权衡理论与破产成本&quot;">​</a></h1><div class="epigraph"><p>若税盾使债务变贵而有利，破产成本使债务变贵而有害，最优资本结构出现在两边际相等处。</p><footer>—— 据 Modigliani and Miller, AER 1963 更正；Kraus and Litzenberger, Journal of Finance 1973；Myers, The Capital Structure Puzzle, Journal of Finance 1984 整理</footer></div><p><a href="/econ/mm-corporate-tax">上一课</a>（MM 与公司税盾）。<a href="/econ/modigliani-miller">莫迪利亚尼–米勒</a>。1958 年的套利已经证明无摩擦时切片无溢价。本课缺口是把最先被放松的两块摩擦放回去：公司所得税让利息可抵扣，破产与财务困境让杠杆有真实成本。目标负债率从这里出现。不重做家庭自制杠杆的套利。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>MM 1963 年更正指出：利息在公司税前扣除，股利不。多一单位债务，政府少收一笔税，这笔税盾的现值可以进入企业总价值。若只有这一块，最优是百分之百债务——与观察到的内部股权、与<a href="/econ/basel-capital">巴塞尔</a>对银行股本的要求都冲突。因此必须有一块随杠杆上升的抵消成本，否则权衡没有内部解。</p><p>成本候选是破产的资源损耗与困境中的激励扭曲：法律费用、资产火灾出售、客户与雇员流失、以及股权在接近破产时的资产替代（赌大的）。Myers（1984）把「税盾对困境成本」称为静态权衡，并立刻指出它预测企业应有一个可计算的目标比率，而现实中的比率调整缓慢、且 internally 融资更常见。本课先把权衡钉住；优序是下一课对「目标比率」的否定。</p><p><span class="marginnote">财务困境成本不必等到法律破产。投资不足（债务积压）与资产替代在违约前就已经改变项目选择。Kraus–Litzenberger 用状态依存把税盾与破产惩罚写进同一偏好。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把杠杆企业价值写成</p> \\[V_L = V_U + \\mathrm{PV}(\\text{税盾}) - \\mathrm{PV}(\\text{困境成本}). \\]<p>\\(V_U\\) 是 MM 1958 的无杠杆价值。税盾在债务永久滚动、税率不变时，常被写成 \\(\\tau_c D\\)；边际税率下降、亏损无法立即抵扣、以及个人层面利息税，都会缩小这块现值。困境成本的现值随违约概率上升，违约概率随杠杆与资产波动上升。最优 \\(D\\) 在边际税盾等于边际困境成本处。</p><p><span class="marginnote">数字实例：债务 \\(D=10\\) 亿、公司税率 \\(\\tau_c=25\\%\\)、债务永久滚动时，税盾现值约 \\(\\tau_c D=2.5\\) 亿；若违约概率 20%、破产时真实损耗 3 亿，困境成本现值约 \\(0.2\\times 3=0.6\\) 亿，净得约 1.9 亿——所谓权衡，就是算这两笔账并找它们的交点。</span></p><p>Kraus 与 Litzenberger（1973）在状态偏好里把同一权衡写清楚：某些状态下债务触发破产惩罚，另一些状态下税盾兑现；最优切片取决于状态价格，不是一个与风险无关的魔法比率。银行版本里，困境成本包含挤兑与处置的外部性，所以私人最优杠杆仍可能高于社会最优——资本监管是把权衡的目标从外部再切一刀。</p>',13)),(E(),s(B,null,{default:t(()=>[i(l,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20VU%5B%22%E6%97%A0%E6%9D%A0%E6%9D%86%E4%BB%B7%E5%80%BC%20VU%22%5D%20--%3E%20VL%5B%22VL%22%5D%0A%20%20TAX%5B%22%E7%A8%8E%E7%9B%BE%E7%8E%B0%E5%80%BC%22%5D%20--%3E%20VL%0A%20%20DIST%5B%22%E5%9B%B0%E5%A2%83%E6%88%90%E6%9C%AC%E7%8E%B0%E5%80%BC%22%5D%20--%3E%20VL%0A%20%20VL%20--%3E%20DSTAR%5B%22%E7%9B%AE%E6%A0%87%E6%9D%A0%E6%9D%86%20D*%22%5D%0A%20%20DSTAR%20--%3E%20MARG%5B%22%E8%BE%B9%E9%99%85%E7%A8%8E%E7%9B%BE%20%3D%20%E8%BE%B9%E9%99%85%E5%9B%B0%E5%A2%83%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"权衡给出可检验的定性预言：税率更高、有形资产更多（困境中可收回）、利润更稳定的企业，目标杠杆更高。预言失败的方式交给 Myers 的谜题，不是本课改写成优序。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"机制是两块现金流对同一切片的相反反应。多借债：支付给债权人的利息少交公司税，状态好时 \\(V\\) 上升；状态坏时控制权转移的成本、以及事前的风险转移，使 \\(V\\) 下降。内部最优是权衡，不是角点。与 1958 年的差别仅在于：家庭不能自制公司税盾，也不能自制破产的法律成本，复制失败，切片开始有关。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：税盾像一张政府送的打折券，每借一元钱就少交一点税；困境成本像卡车超载——多装一箱货多赚一点运费，但翻车的概率与翻车时的损失都在涨。最优装载量在「省下的运费」等于「翻车的期望损失」处。")],-1)),(E(),s(B,null,{default:t(()=>[i(l,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20TD%0A%20%20LEV%5B%22%E6%9D%A0%E6%9D%86%E8%BF%87%E9%AB%98%22%5D%20--%3E%20SUB%5B%22%E8%B5%84%E4%BA%A7%E6%9B%BF%E4%BB%A3%3A%20%E8%82%A1%E4%B8%9C%E6%94%B9%E8%B5%8C%E5%A4%A7%E9%A1%B9%E7%9B%AE%22%5D%0A%20%20SUB%20--%3E%20RISK%5B%22%E4%B8%8B%E8%A1%8C%E6%8D%9F%E5%A4%B1%E8%BD%AC%E7%BB%99%E5%80%BA%E6%9D%83%E4%BA%BA%22%5D%0A%20%20RISK%20--%3E%20VDOWN%5B%22%E4%BC%81%E4%B8%9A%E4%BB%B7%E5%80%BC%E4%B8%8B%E9%99%8D%22%5D%0A%20%20LEV%20--%3E%20OVR%5B%22%E5%80%BA%E5%8A%A1%E7%A7%AF%E5%8E%8B%3A%20%E6%AD%A3%20NPV%20%E9%A1%B9%E7%9B%AE%E8%A2%AB%E6%94%BE%E5%BC%83%22%5D%0A%20%20OVR%20--%3E%20UNDER%5B%22%E6%96%B0%E8%82%A1%E6%9D%83%E5%9C%A8%E4%B8%BA%E5%80%BA%E6%9D%83%E4%BA%BA%E6%89%93%E5%B7%A5%22%5D%0A%20%20UNDER%20--%3E%20VDOWN%0A%20%20VDOWN%20--%3E%20DST%5B%22%E5%9B%B0%E5%A2%83%E6%88%90%E6%9C%AC%E7%8E%B0%E5%80%BC%E4%B8%8A%E5%8D%87%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<p><span class="marginnote">常见误区：初学者容易以为困境成本只有律师费和清算费。实际上违约之前，资产替代和债务积压就已经改变了项目选择——公司还没进法庭，权衡已经开始「罚款」了。</span></p><p>静态权衡把调整成本设为零，企业应随时贴近 \\(D^\\ast\\)。发行成本、回购窗口、市值波动使账面或市值杠杆绕着目标游走。这仍是权衡加摩擦，还不是信息不对称的优序。下一课 Myers–Majluf 会说：即使存在 \\(D^\\ast\\)，被低估的企业也不愿发股去贴近它。</p><h3 id="银行的权衡被监管切开" tabindex="-1">银行的权衡被监管切开 <a class="header-anchor" href="#银行的权衡被监管切开" aria-label="Permalink to &quot;银行的权衡被监管切开&quot;">​</a></h3><p>对非金融企业，\\(D^\\ast\\) 是私人最优。对银行，倒闭的外部性使私人 \\(D^\\ast\\) 高于社会最优，<a href="/econ/basel-capital">巴塞尔</a>相当于把可行集再切一刀。税盾对银行同样存在，存款保险还额外降低私人看到的困境成本——权衡会进一步偏向杠杆。资本监管不是否认税盾，而是不让私人权衡决定社会杠杆。读银行资本时，先写 MM，再写权衡，再写监管切一刀，顺序不能倒。</p><p><span class="marginnote">债务积压（Myers 1977）：杠杆过高时，新股权为债权人「打工」，正 NPV 项目被放弃。这是困境成本的事前版本，不必等到法庭清算。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 \\(\\tau_c D\\) 当成不可错的税盾公式：亏损结转、利息抵扣上限、个人所得税会使有效税盾远小于法定税率乘债务。也不要把评级下调本身当成困境成本——评级是信息，成本是真实资源与激励。权衡不解释为什么盈利企业往往杠杆更低（它们按权衡应更能扛债）；这正是优序要抢的残差。</p><p>本课不写股利，不写自由现金流的代理问题。Jensen 的债务作为纪律，与困境成本方向相反，放到股利课才不会把权衡撑破。</p><p>动态权衡允许 \\(D^\\ast\\) 随盈利与投资机会移动，企业有调整带。带的宽度来自发行成本，不是来自柠檬。柠檬是下一课：发股本身传递类型，成本可以大到使目标比率不再是一阶描述。</p><p>后课默认：权衡给出私人 \\(D^\\ast\\)，来自税盾对困境成本。盈利企业杠杆偏低、发股的负公告，不是本课能吞的残差，交给优序。银行的社会最优杠杆可以低于私人 \\(D^\\ast\\)，监管切一刀并不取消税盾会计。</p><p>\\(\\tau_c D\\) 不是不可错的税盾：亏损结转、抵扣上限、个人所得税都会缩小现值。</p><p>债务积压在违约前就已经改变项目选择。评级下调本身是信息，不是资源成本。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>税盾使债务有利，困境成本使债务有害；内部目标杠杆是权衡。</li><li>复制失败是因为家庭造不出公司税与破产法。</li><li>静态权衡预测可计算的 \\(D^\\ast\\)；现实中的偏离是下一课的缺口。</li><li>出处：MM 1963；Kraus and Litzenberger 1973；Myers 1984。</li></ul>',14))])}const C=o(d,[["render",D]]);export{_ as __pageData,C as default};
